    md43778e90a8c:
        '{0} Nevar iesniegt jaunu foto Boost izmantošanai ({1}); vienīgajam foto jau ir Turbo — Boost izlaists',
    md58389c8dc34: 'Paziņojumu cikls pirms termiņa neizdevās',
